drop view if exists vw_dim_booking;create view vw_dim_bookingasselect	s.id as sk_booking,    -- coalesce(r2.id, r.id, s.id) as id_booking,    coalesce(s."reagendadoDe_id", s.id) as id_booking,    -- coalesce(r2.id, r.id, s.id) = s.id as valid_bookings_not_rescheduled,    max(s.id) over (partition by coalesce(s."reagendadoDe_id", s.id)) = s.id as valid_bookings_not_rescheduled,    s.data as dt_booking,    s.tipo as type,    s."fupVisita" is not null      and s."fupVisita" in ('NaoGostou', 'Talvez', 'VaiNegociar', 'VisitouSozinho')    as confirmed,    s.encerrado as closed,    s."fupVisita" as visit_follow_up,    s."dataFupVisita" as dt_visit_follow_up,    s."reagendadoDe_id" as rescheduled_from_id,    s.visitante_id as id_visitor,    s.visita_id as id_visit,    s.imovel_id as id_property,    s.agente_id as id_agent,    s.atendente_id as id_attendant,    s."fluxoLocacao_id" as id_rental_flow,    s.status,    s."slotDia" as slot_dia,    s."criadoEm" as dt_created,    s."atualizadoEm" as dt_updated,    now()::timestamp as dt_timestampfrom	booking s/*left join(	select distinct        "reagendadoDe_id",        id    from    	booking    where    	"reagendadoDe_id" is not null) ron r."reagendadoDe_id" = s."reagendadoDe_id"left join(	select distinct        "reagendadoDe_id",        id    from    	booking    where    	"reagendadoDe_id" is not null) r2on r2."reagendadoDe_id" = s.id*/-- where  s.id in (145513, 146371, 146372);